entries[347150] = { ["name"] = "Dreiertechnik", ["text"] = "Wirken in 15 sek.\nSo'azmi setzt seine geheime dreiteilige Technik ein.\nBeim Abschluss schleudert er brennende Klingen auf alle Spielercharaktere, die 10 Sek. lang alle 1 Sek. 10910022 Feuerschaden verursachen.\nDieser Zauber muss 3-mal unterbrochen werden, um seinen Einsatz zu verhindern." }
